import numpy as np

# Example 1: np.signbit(np.abs(np.nan))
try:
    result = np.signbit(np.abs(np.nan))
    probe("np.signbit(np.abs(np.nan))", result)
except Exception as e:
    probe("np.signbit(np.abs(np.nan))", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 1
try:
    expected = False
    probe("expected::np.signbit(np.abs(np.nan))", expected)
except Exception as e:
    probe("expected::np.signbit(np.abs(np.nan))", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 2: np.signbit(np.abs(-np.nan))
try:
    result = np.signbit(np.abs(-np.nan))
    probe("np.signbit(np.abs(-np.nan))", result)
except Exception as e:
    probe("np.signbit(np.abs(-np.nan))", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 2
try:
    expected = False
    probe("expected::np.signbit(np.abs(-np.nan))", expected)
except Exception as e:
    probe("expected::np.signbit(np.abs(-np.nan))", "__error__: " + type(e).__name__ + ": " + str(e))

# Example 3: np.signbit applied to np.abs(np.array([np.nan, -np.nan]))
try:
    result = np.signbit(np.abs(np.array([np.nan, -np.nan])))
    probe("np.abs(np.array([np.nan, -np.nan])) passed to np.signbit", result)
except Exception as e:
    probe("np.abs(np.array([np.nan, -np.nan])) passed to np.signbit", "__error__: " + type(e).__name__ + ": " + str(e))

# Expected value for example 3
try:
    expected = np.array([False, False])
    probe("expected::np.abs(np.array([np.nan, -np.nan])) passed to np.signbit", expected)
except Exception as e:
    probe("expected::np.abs(np.array([np.nan, -np.nan])) passed to np.signbit", "__error__: " + type(e).__name__ + ": " + str(e))

# Additional test for different dtypes mentioned in the report
