    try:
        nan_val = dtype(np.nan)
        result = np.signbit(np.abs(nan_val))
        probe(f"np.signbit(np.abs(np.{dtype.__name__}(np.nan)))", result)
    except Exception as e:
        probe(f"np.signbit(np.abs(np.{dtype.__name__}(np.nan)))", "__error__: " + type(e).__name__ + ": " + str(e))

# Test with negative NaN for different dtypes
for dtype in [np.float16, np.float32, np.float64]:
